# Data rows
row_num = 2
for section in data['result']['sections']:
    section_name = section['section_name']

    for q in section['questions']:
        # Section
        ws_detail.cell(row=row_num, column=1, value=section_name)

        # Question ID
        ws_detail.cell(row=row_num, column=2, value=q['question_id'])

        # Question text
        ws_detail.cell(row=row_num, column=3, value=q['question'])

        # Answer
        answer = q.get('answer') or "NOT FOUND"
        ws_detail.cell(row=row_num, column=4, value=answer)

        # Confidence
        conf = q.get('confidence', 0)
        conf_str = f"{conf:.0%}" if conf > 0 else "-"
        ws_detail.cell(row=row_num, column=5, value=conf_str)

        # Pages
        pages = q.get('page_citations', [])
        pages_str = ", ".join(map(str, pages)) if pages else "-"
        ws_detail.cell(row=row_num, column=6, value=pages_str)

        # Footnote
        footnote = q.get('footnote') or ""
        ws_detail.cell(row=row_num, column=7, value=footnote)

        # Apply styling
        fill = answered_fill if q.get('answer') else unanswered_fill
        for col in range(1, 8):
            cell = ws_detail.cell(row=row_num, column=col)
            cell.fill = fill
            cell.border = thin_border
            cell.alignment = Alignment(vertical='top', wrap_text=True)

        row_num += 1

