# Section stats
row_num = 2
for section in data['result']['sections']:
    section_name = section['section_name']
    questions = section['questions']
    total = len(questions)
    answered = sum(1 for q in questions if q.get('answer'))
    confidences = [q['confidence'] for q in questions if q.get('confidence', 0) > 0]
    avg_conf = sum(confidences) / len(confidences) if confidences else 0

    ws_sections.cell(row=row_num, column=1, value=section_name)
    ws_sections.cell(row=row_num, column=2, value=total)
    ws_sections.cell(row=row_num, column=3, value=answered)
    ws_sections.cell(row=row_num, column=4, value=f"{answered/total:.0%}" if total > 0 else "0%")
    ws_sections.cell(row=row_num, column=5, value=f"{avg_conf:.0%}" if avg_conf > 0 else "-")

    for col in range(1, 6):
        cell = ws_sections.cell(row=row_num, column=col)
        cell.border = thin_border
        if col >= 2:
            cell.alignment = Alignment(horizontal='center')

    row_num += 1

